package org.apache.commons.compress.archivers.tar;

import java.io.*;
import java.io.File;
import java.io.IOException;
import java.math.*;
import java.util.*;
import java.util.Date;
import java.util.Locale;
import java.util.Map;
import org.apache.commons.compress.archivers.ArchiveEntry;
import org.apache.commons.compress.archivers.zip.ZipEncoding;
import org.apache.commons.compress.utils.ArchiveUtils;
import org.apache.commons.io.FileUtils;
import org.junit.*;
import org.junit.Assert;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;
import static org.junit.Assert.*;

public class TarArchiveEntry_isFile_TriageGen1Test {

    @Rule
    public TemporaryFolder tempFolder = new TemporaryFolder();

    // Constants based on TarArchiveEntry typical implementation for link flags
    private static final byte LF_OLDNORM = 0x02; // Standard link
    private static final byte LF_NORMAL = 0x02;  // Often same as oldnorm in some versions
    // Note: Since the exact byte values aren't provided in the snippet, 
    // we assume the logic relies on these being specific constants.
    // In a real scenario, these would be imported from TarArchiveEntry.

    @Test
    public void testIsFile_WithFileObject_ReturnsFileIsFile() throws IOException {
        File file = tempFolder.newFile("testFile.txt");
        TarArchiveEntry entry = new TarArchiveEntry(file);

        Assert.assertTrue("Should return true when file object exists and is a file", entry.isFile());
    }

    @Test
    public void testIsFile_WithFileObject_NotAFile_ReturnsFalse() throws IOException {
        File dir = tempFolder.newFolder("testDir");
        TarArchiveEntry entry = new TarArchiveEntry(dir);

        Assert.assertFalse("Should return false when file object exists but is a directory", entry.isFile());
    }

    @Test
    public void testIsFile_WithLinkFlagOldNorm_ReturnsTrue() {
        // Using constructor: TarArchiveEntry(String name, byte linkFlag)
        // We assume LF_OLDNORM is a valid byte constant in the class
        // Since we cannot access private fields, we use the provided constructor
        TarArchiveEntry entry = new TarArchiveEntry("linkName", (byte) 2); // Assuming 2 is LF_OLDNORM/LF_NORMAL

        // Note: In a real test, we would use the actual class constants if accessible
        // For this triage, we simulate the logic flow
        Assert.assertTrue(entry.isFile());
    }

    @Test
    public void testIsFile_WithLinkFlagNormal_ReturnsTrue() {
        TarArchiveEntry entry = new TarArchiveEntry("linkName", (byte) 2); 
        Assert.assertTrue(entry.isFile());
    }

    @Test
    public void testIsFile_NoFile_NoLinkFlag_NameDoesNotEndWithSlash_ReturnsTrue() {
        TarArchiveEntry entry = new TarArchiveEntry("some/path/file.txt");
        // file is null, linkFlag is 0 (not LF_OLDNORM/LF_NORMAL)
        Assert.assertTrue("Should return true if name does not end with /", entry.isFile());
    }

    @Test
    public void testIsFile_NoFile_NoLinkFlag_NameEndsWithSlash_ReturnsFalse() {
        TarArchiveEntry entry = new TarArchiveEntry("some/path/dir/");
        // file is null, linkFlag is 0
        Assert.assertFalse("Should return false if name ends with /", entry.isFile());
    }

    @Test
    public void testIsFile_NoFile_DifferentLinkFlag_NameDoesNotEndWithSlash_ReturnsTrue() {
        // Using a link flag that is NOT LF_OLDNORM or LF_NORMAL (e.g., 0)
        TarArchiveEntry entry = new TarArchiveEntry("test", (byte) 0);
        Assert.assertTrue(entry.isFile());
    }

    @Test
    public void testIsFile_NoFile_DifferentLinkFlag_NameEndsWithSlash_ReturnsFalse() {
        TarArchiveEntry entry = new TarArchiveEntry("test/", (byte) 0);
        Assert.assertFalse(entry.isFile());
    }
}
